import * as THREE from 'three';
import WebGPURenderer from 'three/addons/renderers/webgpu/WebGPURenderer.js';

export const createRenderer = (canvas) => {
  try {
    // WebGPURenderer initialization (will throw if WebGPU is unsupported in this three.js version/env without flags)
    const renderer = new WebGPURenderer({ canvas, antialias: false, alpha: true });
    return renderer;
  } catch (e) {
    console.warn("WebGPU not supported or initialization failed, falling back to WebGLRenderer.");
    return new THREE.WebGLRenderer({ canvas, antialias: false, alpha: true });
  }
};
